#!/usr/bin/env node
/**
 * Validates the committed lead files.
 *
 * The files are generated by `npm run leads:refresh`, which reads public
 * listings. This check runs offline and enforces the promises the files make:
 * exactly 100 rows each, one real https source per row, no invented or private
 * contact data, and a stated basis for every name.
 *
 * A row that says "Not published" is fine. A row that guesses is not, so the
 * enums below are closed: an unknown basis or verification value fails.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dir = path.join(root, 'docs', 'leads');

let failures = 0;
function check(name, ok, detail) {
    console.log((ok ? 'ok   ' : 'FAIL ') + name + (ok || !detail ? '' : ` (${detail})`));
    if (!ok) failures += 1;
}

function parseCsv(text) {
    const rows = [];
    let row = [];
    let cell = '';
    let quoted = false;
    for (let i = 0; i < text.length; i += 1) {
        const ch = text[i];
        if (quoted) {
            if (ch === '"' && text[i + 1] === '"') { cell += '"'; i += 1; }
            else if (ch === '"') quoted = false;
            else cell += ch;
        } else if (ch === '"') quoted = true;
        else if (ch === ',') { row.push(cell); cell = ''; }
        else if (ch === '\n') { row.push(cell); rows.push(row); row = []; cell = ''; }
        else if (ch !== '\r') cell += ch;
    }
    if (cell || row.length) { row.push(cell); rows.push(row); }
    return rows.filter((r) => r.length > 1 || (r.length === 1 && r[0].trim()));
}

const HOSTS = new Set([
    'n8nexperts.io', 'www.freelancermap.com', 'github.com',
    'www.freelancer.com', 'remoteok.com', 'weworkremotely.com',
    'news.ycombinator.com'
]);

const SERVICE = /excel|spreadsheet|google sheets|vba|macro|dashboard|power bi|tableau|looker|pdf|report|brochure|pitch deck|word doc|ocr|data entry|data cleaning|data collection|scrap|crawl|wordpress|shopify|woocommerce|landing page|web ?site|webflow|react|next\.?js|frontend|front-end|full[- ]stack|n8n|zapier|make\.com|airtable|automation|workflow|chatbot|ai agent|llm|openai|python|powerpoint|presentation|developer|engineer/i;

const SPECS = {
    clients: {
        file: 'clients.csv',
        idPrefix: 'C',
        urlColumn: 'post_url',
        columns: ['id', 'client', 'client_basis', 'project_title', 'skills', 'country',
            'compensation', 'platform', 'post_url', 'source_kind', 'verification', 'checked_at', 'notes'],
        enums: {
            client_basis: ['published_name', 'public_handle', 'not_published'],
            source_kind: ['public_job_post'],
            verification: ['listing_page_fetched', 'api_record', 'profile_page_fetched']
        },
        textColumn: 'project_title',
        nameColumn: 'client'
    },
    freelancers: {
        file: 'freelancers.csv',
        idPrefix: 'F',
        urlColumn: 'profile_url',
        columns: ['id', 'name', 'name_basis', 'headline', 'skills', 'country', 'platform',
            'profile_url', 'source_kind', 'verification', 'checked_at', 'notes'],
        enums: {
            name_basis: ['published_name', 'url_handle', 'not_published'],
            source_kind: ['marketplace_profile', 'public_dev_profile'],
            verification: ['listing_page_fetched', 'api_record', 'profile_page_fetched']
        },
        textColumn: 'headline',
        nameColumn: 'name'
    }
};

for (const [label, spec] of Object.entries(SPECS)) {
    const file = path.join(dir, spec.file);
    if (!fs.existsSync(file)) {
        check(`${label}: file exists`, false, spec.file);
        continue;
    }
    const rows = parseCsv(fs.readFileSync(file, 'utf8'));
    const header = rows[0] || [];
    const data = rows.slice(1);

    check(`${label}: header matches the documented columns`,
        header.join(',') === spec.columns.join(','), header.join(','));
    check(`${label}: exactly 100 rows`, data.length === 100, String(data.length));

    const missing = [];
    const badUrls = [];
    const badEnums = [];
    const badDates = [];
    const leaked = [];
    const irrelevant = [];
    const badIds = [];
    const ids = new Set();
    const urls = new Set();
    const platforms = new Set();

    data.forEach((cells, index) => {
        const row = Object.fromEntries(spec.columns.map((c, i) => [c, cells[i] ?? '']));
        const expectedId = `${spec.idPrefix}${String(index + 1).padStart(3, '0')}`;
        if (row.id !== expectedId) badIds.push(row.id || '(empty)');
        if (ids.has(row.id)) badIds.push(`dup ${row.id}`);
        ids.add(row.id);

        for (const column of spec.columns) {
            if (!String(row[column]).trim()) missing.push(`${row.id}:${column}`);
        }

        const url = row[spec.urlColumn];
        try {
            const parsed = new URL(url);
            if (parsed.protocol !== 'https:') badUrls.push(`${row.id} ${url}`);
            else if (!HOSTS.has(parsed.hostname)) badUrls.push(`${row.id} ${parsed.hostname}`);
        } catch {
            badUrls.push(`${row.id} ${url || '(none)'}`);
        }
        if (urls.has(url)) badUrls.push(`${row.id} duplicate ${url}`);
        urls.add(url);

        for (const [column, allowed] of Object.entries(spec.enums)) {
            if (!allowed.includes(row[column])) badEnums.push(`${row.id}:${column}=${row[column]}`);
        }
        if (!/^\d{4}-\d{2}-\d{2}$/.test(row.checked_at)) badDates.push(`${row.id}:${row.checked_at}`);

        // No contact data and no placeholder junk, anywhere in the row.
        const all = cells.join(' ');
        if (/[\w.+-]+@[\w-]+\.[\w.]+/.test(all)) leaked.push(`${row.id}: email`);
        if (/\+\d[\d\s-]{7,}/.test(all)) leaked.push(`${row.id}: phone`);
        if (/example\.(com|org)|TODO|FIXME|lorem ipsum/i.test(all)) leaked.push(`${row.id}: placeholder`);

        if (!SERVICE.test(`${row[spec.textColumn]} ${row.skills}`)) irrelevant.push(row.id);
        platforms.add(row.platform);
    });

    check(`${label}: ids are sequential`, badIds.length === 0, badIds.slice(0, 3).join(', '));
    check(`${label}: no empty cell`, missing.length === 0, missing.slice(0, 3).join(', '));
    check(`${label}: every source is a real https page on a known host`,
        badUrls.length === 0, badUrls.slice(0, 3).join(', '));
    check(`${label}: every basis and verification value is known`,
        badEnums.length === 0, badEnums.slice(0, 3).join(', '));
    check(`${label}: checked_at is a date`, badDates.length === 0, badDates.slice(0, 3).join(', '));
    check(`${label}: no email, phone or placeholder text`, leaked.length === 0, leaked.slice(0, 3).join(', '));
    check(`${label}: every row is relevant to a Gahonsh service`,
        irrelevant.length === 0, irrelevant.slice(0, 5).join(', '));
    check(`${label}: at least three platforms are represented`, platforms.size >= 3,
        [...platforms].join(', '));

    if (label === 'clients') {
        const named = data.filter((cells) => cells[spec.columns.indexOf('client_basis')] !== 'not_published');
        check('clients: at least 20 rows name the buyer', named.length >= 20, String(named.length));
    }
    if (label === 'freelancers') {
        const named = data.filter((cells) => cells[spec.columns.indexOf('name_basis')] !== 'not_published');
        check('freelancers: at least 50 rows carry a name or handle', named.length >= 50, String(named.length));
    }
}

const readme = path.join(dir, 'README.md');
check('docs/leads/README.md explains the columns', fs.existsSync(readme));

if (failures) {
    console.error(`\nlead check failed: ${failures} case(s)`);
    process.exit(1);
}
console.log('\nlead check passed.');
